'use strict';
// Automation: Proxmox tags (display, filter, edit), scheduled actions,
// reports (CSV export and a printable capacity report) and the change
// history of a single guest (Orbit operations merged with Proxmox tasks).

Object.assign(icons,{clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',file:'<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5M9 13h6M9 17h6"/>',tag:'<path d="M20.6 13.4 13.4 20.6a2 2 0 0 1-2.8 0L3 13V3h10l7.6 7.6a2 2 0 0 1 0 2.8z"/><circle cx="7.5" cy="7.5" r="1.5"/>'});
Object.assign(pageTitles,{schedules:'Geplante Aktionen',reports:'Berichte'});
Object.assign(pageIcons,{schedules:'clock',reports:'file'});
{const ops=infraNav.find(g=>g[0]==='Operations');if(ops&&!ops[2].some(i=>i[0]==='schedules'))ops[2].push(['schedules','Geplante Aktionen'],['reports','Berichte'])}
const canOperate=()=>state.mode==='demo'||['admin','operator'].includes(state.user?.role);

/* Tags -------------------------------------------------------------------- */
function guestTagList(v){return String(v?.tags||'').toLowerCase().split(/[;,\s]+/).filter(Boolean)}
function tagHue(t){let h=7;for(const c of t)h=(h*31+c.charCodeAt(0))%360;return h}
function tagChip(t){return `<span class="tag-chip" style="--tag-h:${tagHue(t)}">${esc(t)}</span>`}
function tagChips(v){const t=guestTagList(v);return t.length?`<span class="tag-list">${t.map(tagChip).join('')}</span>`:''}
function allTags(list=state.resources){return [...new Set(list.filter(r=>['qemu','lxc'].includes(r.type)).flatMap(guestTagList))].sort()}
function tagFilterSelect(list){const tags=allTags(list);if(!tags.length)return '';return `<label class="tag-filter"><span class="sr-only">Nach Tag filtern</span>${icon('tag')}<select id="vm-tag-filter" aria-label="Nach Tag filtern"><option value="">Alle Tags</option>${tags.map(t=>`<option value="${esc(t)}" ${state.vmTag===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`}
function tagMatches(v){return !state.vmTag||guestTagList(v).includes(state.vmTag)}
function tagEditor(v){return `${tagChips(v)||'<span class="muted">Keine</span>'}${canOperate()&&!isTemplate(v)?` <button type="button" class="text-button" data-edit-tags="${esc(v.connection_id)}:${esc(v.vmid)}">Bearbeiten</button>`:''}`}
function tagModal(ref){const v=state.resources.find(r=>r.connection_id+':'+r.vmid===ref);if(!v)return;const known=allTags().filter(t=>!guestTagList(v).includes(t));
openModal('TAGS',v.name||'VM '+v.vmid,`<form id="tag-form">${field('Tags (durch Komma oder Leerzeichen getrennt)','tags',guestTagList(v).join(', '),{optional:true,placeholder:'prod, web, backup-daily'})}${known.length?`<div class="tag-suggest"><span class="muted">Vorhanden:</span> ${known.map(t=>`<button type="button" class="tag-chip as-button" style="--tag-h:${tagHue(t)}" data-add-tag="${esc(t)}">${esc(t)}</button>`).join('')}</div>`:''}<p class="muted">Tags werden in Proxmox gespeichert und gelten dort ebenso. Erlaubt: a–z, 0–9, _ + . -</p><div data-form-error class="hint error"></div><div class="modal-foot"><button type="button" data-cancel>Abbrechen</button><button class="primary">Speichern</button></div></form>`);
const form=$('#tag-form');for(const b of form.querySelectorAll('[data-add-tag]'))b.onclick=()=>{const cur=form.elements.tags.value.split(/[;,\s]+/).filter(Boolean);if(!cur.includes(b.dataset.addTag))cur.push(b.dataset.addTag);form.elements.tags.value=cur.join(', ');b.remove()};
form.onsubmit=async e=>{e.preventDefault();const raw=form.elements.tags.value.trim(),list=raw.toLowerCase().split(/[;,\s]+/).filter(Boolean);const bad=list.find(t=>!/^[a-z0-9_][a-z0-9_+.-]{0,63}$/.test(t));if(bad){formError(`Ungültiger Tag „${bad}“.`);return}setModalBusy(true);try{if(state.mode==='demo'){v.tags=[...new Set(list)].sort().join(';');closeModal(true);toast('Tags gespeichert.');render();return}const op=await api('operations',{method:'POST',body:JSON.stringify({action:'tags',tags:list.join(';'),connection_id:v.connection_id,node:v.node,vmid:v.vmid,confirm_name:v.name,request_key:newRequestKey()})});state.operations.unshift(op);closeModal(true);operationLog(op.id)}catch(err){setModalBusy(false);formError(err.message)}}}

/* Change history per guest -------------------------------------------------- */
function historyState(){return state.history||(state.history={})}
function demoHistory(v){const now=Date.now()/1000,ops=state.operations.filter(o=>o.connection_id===v.connection_id&&+o.vmid===+v.vmid).map(o=>({source:'orbit',at:o.created,action:o.action,status:o.status,user:o.requested_by||'admin',node:o.node,args:o.args||{},message:(o.events||[]).slice(-1)[0]?.message||''}));return [...ops,{source:'orbit',at:now-3600*5,action:'metadata',status:'completed',user:'admin',node:v.node,args:{name:v.name,onboot:1},message:'Proxmox hat die Aktion erfolgreich abgeschlossen.'},{source:'proxmox',at:now-3600*5,end:now-3600*5+2,action:'qmconfig',status:'OK',user:'orbit@pve!orbit',node:v.node},{source:'proxmox',at:now-86400,end:now-86400+340,action:'vzdump',status:'OK',user:'root@pam',node:v.node},{source:'orbit',at:now-86400*2,action:'snapshot',status:'completed',user:'Zeitplan Nachts (Snapshot)',node:v.node,args:{snapname:'auto_3f2a1c_20261101T0200'},message:'Proxmox hat die Aktion erfolgreich abgeschlossen.'},{source:'proxmox',at:now-86400*3,end:now-86400*3+40,action:'qmigrate',status:'OK',user:'admin@pve',node:'pve-01'}].sort((a,b)=>b.at-a.at)}
async function loadHistory(v,force=false){const key=v.connection_id+':'+v.vmid,h=historyState(),e=h[key]||(h[key]={});if(e.busy||(!force&&e.at&&Date.now()-e.at<20000))return;e.busy=true;try{e.rows=state.mode==='demo'?demoHistory(v):await api('connections/'+encodeURIComponent(v.connection_id)+'/guest-history?vmid='+encodeURIComponent(v.vmid));e.error=''}catch(err){e.error=err.message}finally{e.busy=false;e.at=Date.now()}if(state.page==='object')render()}
const historyArgLabels={snapname:'Snapshot',target:'Ziel',storage:'Storage',cores:'vCPU',memory:'RAM (MiB)',name:'Name',hostname:'Name',newid:'Neue VMID',tags:'Tags',state:'HA',onboot:'Autostart',description:'Beschreibung',full:'Vollklon',online:'Live'};
function historyDetail(r){if(r.source==='proxmox')return r.end?`Dauer ${Math.max(1,Math.round(r.end-r.at))} s`:'läuft';const args=Object.entries(r.args||{}).filter(([k,v])=>historyArgLabels[k]&&v!==''&&v!=null).map(([k,v])=>`${historyArgLabels[k]}: ${k==='description'?String(v).slice(0,40):v}`);return [args.join(' · '),r.status==='failed'||r.status==='needs_attention'?r.message:''].filter(Boolean).join(' — ')}
function historyStatus(r){if(r.source==='proxmox'){if(r.status==='running')return statusTag('running');return r.status==='OK'?'<span class="status-tag ok"><span class="dot"></span>OK</span>':/^WARNINGS/.test(r.status)?`<span class="status-tag warn"><span class="dot amber"></span>${esc(r.status)}</span>`:`<span class="status-tag fail"><span class="dot"></span>${esc(String(r.status).slice(0,60))}</span>`}return statusTag(r.status)}
function historyPanel(v){const key=v.connection_id+':'+v.vmid,e=historyState()[key]||{},rows=e.rows||[],src=state.historySource||'all',shown=rows.filter(r=>src==='all'||r.source===src);if(!e.at&&!e.busy)setTimeout(()=>loadHistory(v),0);
return `<section class="panel history-panel"><div class="table-toolbar"><h2>Änderungsprotokoll</h2><div class="filter-chips" role="group" aria-label="Quelle">${[['all','Alle'],['orbit','Orbit-Aktionen'],['proxmox','Proxmox-Tasks']].map(([k,l])=>`<button type="button" class="chip ${src===k?'selected':''}" data-history-source="${k}" aria-pressed="${src===k}">${l}</button>`).join('')}</div><button type="button" data-history-refresh>${icon('refresh')} Aktualisieren</button></div>${e.error?`<div class="hint error">${esc(e.error)}</div>`:''}${!e.rows?'<div class="loading">Protokoll wird geladen …</div>':shown.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Zeit</th><th>Quelle</th><th>Aktion</th><th>Benutzer</th><th>Host</th><th>Status</th><th>Details</th></tr></thead><tbody>${shown.map(r=>`<tr><td class="mono nowrap">${esc(new Date(r.at*1000).toLocaleString('de-DE',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}))}</td><td><span class="type-tag">${r.source==='orbit'?'Orbit':'Proxmox'}</span></td><td>${r.source==='proxmox'&&r.upid?`<button type="button" class="text-button" data-task-log="${esc(v.connection_id)}|${esc(r.node)}|${esc(r.upid)}">${esc(pveTaskTypes[r.action]||r.action)}</button>`:esc(r.source==='proxmox'?(pveTaskTypes[r.action]||r.action):(operationLabels[r.action]||r.action))}</td><td>${esc(r.user||'—')}</td><td>${esc(r.node||'—')}</td><td>${historyStatus(r)}</td><td class="muted">${esc(historyDetail(r))}</td></tr>`).join('')}</tbody></table></div>`:empty('activity','Keine Einträge','Für diesen Gast sind noch keine Änderungen protokolliert.')}<p class="muted history-note">Orbit-Aktionen zeigen, wer was ausgelöst hat; Proxmox-Tasks umfassen auch Änderungen außerhalb von Orbit (alle Hosts des Clusters).</p></section>`}

/* Scheduled actions --------------------------------------------------------- */
const scheduleActionNames={start:'Starten',shutdown:'Herunterfahren',reboot:'Neu starten',stop:'Hart ausschalten',snapshot:'Snapshot (mit Aufbewahrung)',backup:'Backup'};
const weekdayNames=['So','Mo','Di','Mi','Do','Fr','Sa'],weekdayOrder=[1,2,3,4,5,6,0];
function scheduleState(){return state.schedulesData||(state.schedulesData={list:[],timezone:'',at:0,busy:false,error:''})}
function demoSchedules(){const now=Date.now()/1000;return{timezone:'Europe/Berlin',schedules:[{id:'s3f2a1c9d0e1b',name:'Nachts Snapshot Web',action:'snapshot',kind:'daily',time:'02:00',days:[],connection_id:'demo',target:'tag',tag:'web',keep:7,enabled:true,next_run:now+3600*9,created_by:'admin',last_run:{at:now-3600*15,results:[{vmid:100,name:'web-01',status:'queued'},{vmid:101,name:'web-02',status:'queued'}]}},{id:'s9a8b7c6d5e4f',name:'Testumgebung abends aus',action:'shutdown',kind:'daily',time:'20:00',days:[1,2,3,4,5],connection_id:'demo',target:'vmids',vmids:[104,105],enabled:true,next_run:now+3600*3,created_by:'admin',last_run:{at:now-86400+3600*3,results:[{vmid:104,name:'test-01',status:'queued'},{vmid:105,name:'test-02',status:'skipped',message:'Übersprungen: läuft nicht.'}]}},{id:'s1b2c3d4e5f60',name:'Wartungsfenster DB',action:'reboot',kind:'once',date:new Date(Date.now()+86400000*4).toISOString().slice(0,10),time:'22:30',days:[],connection_id:'demo',target:'vmids',vmids:[102],enabled:false,next_run:now+86400*4,created_by:'admin'}]}}
async function loadSchedules(force=false){const s=scheduleState();if(s.busy||(!force&&s.at&&Date.now()-s.at<15000))return;s.busy=true;try{const d=state.mode==='demo'?(s.demo||(s.demo=demoSchedules())):await api('schedules');s.list=d.schedules||[];s.timezone=d.timezone||'';s.error=''}catch(e){s.error=e.message}finally{s.busy=false;s.at=Date.now()}if(state.page==='schedules')render()}
function scheduleWhen(sc){const t=sc.time;if(sc.kind==='once')return `Einmalig am ${new Date(sc.date+'T00:00').toLocaleDateString('de-DE')} um ${t}`;const d=(sc.days||[]).map(Number);if(!d.length||d.length===7)return `Täglich ${t}`;if(d.length===5&&[1,2,3,4,5].every(x=>d.includes(x)))return `Werktags ${t}`;if(d.length===2&&d.includes(0)&&d.includes(6))return `Wochenende ${t}`;return weekdayOrder.filter(x=>d.includes(x)).map(x=>weekdayNames[x]).join(', ')+' '+t}
function scheduleTarget(sc){return sc.target==='tag'?`Tag ${tagChip(sc.tag)}`:`VMID ${esc((sc.vmids||[]).join(', '))}`}
function runSummary(run){if(!run)return '<span class="muted">Noch nie</span>';const r=run.results||[],q=r.filter(x=>x.status==='queued').length,sk=r.filter(x=>x.status==='skipped').length,f=r.filter(x=>x.status==='failed').length;return `<span class="nowrap">${esc(new Date(run.at*1000).toLocaleString('de-DE',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}))}</span><small class="${run.error||f?'text-fail':'muted'}">${run.error?esc(run.error):`${q} eingeplant${sk?` · ${sk} übersprungen`:''}${f?` · ${f} Fehler`:''}`}</small>`}
function schedulesPage(){const s=scheduleState(),admin=isAdmin();if(!s.at&&!s.busy)setTimeout(loadSchedules,0);
return head('','Geplante Aktionen','Power-Aktionen, Snapshots und Backups automatisch nach Zeitplan – für feste VMIDs oder alle Gäste mit einem Tag. Jede Ausführung erscheint unter Aufgaben und im Änderungsprotokoll.',refreshButton()+(admin?`<button class="primary" data-schedule-edit="">${icon('plus')} Zeitplan anlegen</button>`:''))+`${s.error?`<div class="hint error">${esc(s.error)}</div>`:''}<section class="panel">${!s.at?'<div class="loading">Zeitpläne werden geladen …</div>':s.list.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Name</th><th>Aktion</th><th>Ziel</th><th>Termin</th><th>Letzter Lauf</th><th>Status</th><th></th></tr></thead><tbody>${s.list.map(sc=>`<tr><td><b>${esc(sc.name)}</b><small class="muted">${esc(state.connections.find(c=>c.id===sc.connection_id)?.name||sc.connection_id)}</small></td><td>${esc(scheduleActionNames[sc.action]||sc.action)}${sc.action==='snapshot'?`<small class="muted">${esc(sc.keep)} behalten</small>`:sc.action==='backup'?`<small class="muted">${esc(sc.storage)}</small>`:''}</td><td>${scheduleTarget(sc)}</td><td>${esc(scheduleWhen(sc))}<small class="muted">${sc.enabled&&sc.next_run?'Nächster Lauf '+esc(new Date(sc.next_run*1000).toLocaleString('de-DE',{weekday:'short',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})):'Kein nächster Lauf'}</small></td><td>${sc.last_run?`<button type="button" class="text-button run-summary" data-schedule-result="${esc(sc.id)}">${runSummary(sc.last_run)}</button>`:runSummary(null)}</td><td>${sc.enabled?'<span class="status-tag ok"><span class="dot"></span>Aktiv</span>':'<span class="status-tag neutral"><span class="dot"></span>Pausiert</span>'}</td><td class="row-actions">${admin?`<details class="action-menu"><summary aria-label="Aktionen für ${esc(sc.name)}">Aktionen ${icon('arrow')}</summary><div class="action-menu-list" role="menu"><button type="button" role="menuitem" data-schedule-run="${esc(sc.id)}">Jetzt ausführen</button><button type="button" role="menuitem" data-schedule-edit="${esc(sc.id)}">Bearbeiten</button><button type="button" role="menuitem" class="danger-item" data-schedule-delete="${esc(sc.id)}">Löschen</button></div></details>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('clock','Keine geplanten Aktionen',admin?'Zum Beispiel Testsysteme abends herunterfahren oder nachts Snapshots mit Aufbewahrung anlegen.':'Administratoren können Zeitpläne anlegen.')}</section><p class="muted schedule-note">Zeitzone des Orbit-Servers: <b>${esc(s.timezone||'—')}</b>. Verpasste Termine (Orbit nicht erreichbar) werden nach einer Stunde übersprungen und protokolliert.</p>`}
function scheduleModal(id){const s=scheduleState(),sc=id?s.list.find(x=>x.id===id):null,pve=state.connections.filter(c=>c.kind!=='pbs'),cid=sc?.connection_id||pve[0]?.id||'demo',days=(sc?.days||[]).map(Number),kind=sc?.kind||'daily',target=sc?.target||'vmids';
openModal('GEPLANTE AKTION',sc?'Zeitplan bearbeiten':'Zeitplan anlegen',`<form id="schedule-form"><div class="formgrid">${field('Name','name',sc?.name||'',{placeholder:'z. B. Testumgebung abends aus'})}${selectField('Cluster','connection_id',pve.map(c=>option(c.id,c.name,c.id===cid)).join('')||option('demo','Demo',true))}${selectField('Aktion','action',Object.entries(scheduleActionNames).map(([k,l])=>option(k,l,(sc?.action||'shutdown')===k)).join(''))}<div data-opt="snapshot">${field('Snapshots behalten','keep',sc?.keep||7,{type:'number',min:1,max:100})}</div><div data-opt="backup">${selectField('Backup-Storage','storage',backupStorages(cid).map(x=>option(x,x,sc?.storage===x)).join('')||option('','Kein Backup-Storage',true))}</div></div>
<label>Ziel</label><div class="segmented">${[['vmids','VMIDs'],['tag','Tag']].map(([k,l])=>`<label><input type="radio" name="target" value="${k}" ${target===k?'checked':''}> ${l}</label>`).join('')}</div>
<div class="formgrid"><div data-target="vmids">${field('VMIDs','vmids',(sc?.vmids||[]).join(', '),{optional:true,placeholder:'100, 101, 102'})}</div><div data-target="tag">${field('Tag','tag',sc?.tag||'',{optional:true,placeholder:'z. B. test'})}<datalist id="schedule-tags">${allTags().map(t=>`<option value="${esc(t)}">`).join('')}</datalist></div></div>
<label>Wann</label><div class="segmented">${[['daily','Wiederkehrend'],['once','Einmalig']].map(([k,l])=>`<label><input type="radio" name="kind" value="${k}" ${kind===k?'checked':''}> ${l}</label>`).join('')}</div>
<div class="formgrid">${field('Uhrzeit','time',sc?.time||'22:00',{type:'time'})}<div data-kind="once">${field('Datum','date',sc?.date||new Date(Date.now()+86400000).toISOString().slice(0,10),{type:'date',optional:true})}</div></div>
<div data-kind="daily"><div class="weekday-picker" role="group" aria-label="Wochentage (keine Auswahl = täglich)">${weekdayOrder.map(d=>`<label><input type="checkbox" name="day" value="${d}" ${days.includes(d)?'checked':''}><span>${weekdayNames[d]}</span></label>`).join('')}</div><p class="muted">Keine Auswahl bedeutet täglich.</p></div>
<label class="checkbox" data-opt="stop"><input type="checkbox" name="acknowledge"> Mir ist bewusst, dass hartes Ausschalten wie Stromkabel-Ziehen wirkt.</label>
<label class="checkbox"><input type="checkbox" name="enabled" ${!sc||sc.enabled?'checked':''}> Zeitplan aktiv</label><div data-form-error class="hint error"></div><div class="modal-foot"><button type="button" data-cancel>Abbrechen</button><button class="primary">Speichern</button></div></form>`);
const form=$('#schedule-form'),f=form.elements;f.tag.setAttribute('list','schedule-tags');
const sync=()=>{for(const el of form.querySelectorAll('[data-opt]'))el.hidden=el.dataset.opt!==f.action.value;for(const el of form.querySelectorAll('[data-target]'))el.hidden=el.dataset.target!==f.target.value;for(const el of form.querySelectorAll('[data-kind]'))el.hidden=el.dataset.kind!==f.kind.value};sync();form.onchange=sync;
form.onsubmit=async e=>{e.preventDefault();const body={name:f.name.value.trim(),connection_id:f.connection_id.value,action:f.action.value,target:f.target.value,vmids:f.vmids.value,tag:f.tag.value.trim(),kind:f.kind.value,time:f.time.value,date:f.date.value,days:[...form.querySelectorAll('[name=day]:checked')].map(x=>+x.value),keep:+f.keep.value,storage:f.storage.value,acknowledge:f.acknowledge.checked,enabled:f.enabled.checked};if(body.action==='stop'&&!body.acknowledge){formError('Hartes Ausschalten bestätigen.');return}setModalBusy(true);try{if(state.mode==='demo'){const list=s.demo.schedules,item={...(sc||{id:'s'+Math.random().toString(16).slice(2,14)}),...body,vmids:body.vmids.split(/[\s,;]+/).filter(Boolean).map(Number),next_run:Date.now()/1000+3600};if(sc)Object.assign(sc,item);else list.push(item)}else await api('schedules'+(sc?'/'+encodeURIComponent(sc.id):''),{method:'POST',body:JSON.stringify(body)});closeModal(true);toast('Zeitplan gespeichert.');await loadSchedules(true);render()}catch(err){setModalBusy(false);formError(err.message)}}}
function scheduleResultModal(sc,run){const r=run?.results||[];openModal('GEPLANTE AKTION',sc.name+' – letzter Lauf',`${run?.error?`<div class="hint error">${esc(run.error)}</div>`:''}${r.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Gast</th><th>Host</th><th>Ergebnis</th></tr></thead><tbody>${r.map(x=>`<tr><td><b>${esc(x.name||'')}</b> <span class="muted mono">${esc(x.vmid)}</span></td><td>${esc(x.node||'—')}</td><td>${x.status==='queued'?`<span class="status-tag ok"><span class="dot"></span>Eingeplant</span>${x.operation_id?` <button type="button" class="text-button" data-open-op="${esc(x.operation_id)}">Aufgabe</button>`:''}`:x.status==='skipped'?`<span class="status-tag neutral"><span class="dot"></span>${esc(x.message||'Übersprungen')}</span>`:`<span class="status-tag fail"><span class="dot"></span>${esc(x.message||'Fehler')}</span>`}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Keine passenden Gäste gefunden.</p>'}<div class="modal-foot"><button data-cancel>Schließen</button></div>`);for(const b of modal.querySelectorAll('[data-open-op]'))b.onclick=()=>operationLog(b.dataset.openOp)}

/* Reports ------------------------------------------------------------------- */
function csvCell(v){const s=String(v??'');return /[";\n\r]/.test(s)||/^[=+\-@]/.test(s)?'"'+(/^[=+\-@]/.test(s)?"'":'')+s.replace(/"/g,'""')+'"':s}
function downloadCSV(name,header,rows){const text='﻿'+[header,...rows].map(r=>r.map(csvCell).join(';')).join('\r\n');if(typeof Blob==='undefined'||typeof URL?.createObjectURL!=='function'){state.lastReport=text;return text}const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);return text}
const connName=id=>state.connections.find(c=>c.id===id)?.name||id;
const gib=b=>(Number(b||0)/1073741824).toFixed(1).replace('.',',');
const stamp=()=>new Date().toISOString().slice(0,10);
const reportDefs={
 guests:['VMs & Container','Alle Gäste mit Status, Platzierung, Ressourcen und Tags.',()=>downloadCSV(`orbit-gaeste-${stamp()}.csv`,['Cluster','VMID','Name','Typ','Status','Host','vCPU','RAM zugewiesen (GiB)','RAM belegt (GiB)','Disk (GiB)','CPU-Last %','Uptime (h)','Tags','Vorlage'],state.resources.filter(r=>['qemu','lxc'].includes(r.type)).sort((a,b)=>a.vmid-b.vmid).map(v=>[connName(v.connection_id),v.vmid,v.name,v.type==='lxc'?'LXC':'QEMU',v.status,v.node,v.maxcpu,gib(v.maxmem),v.status==='running'?gib(v.mem):'',gib(v.maxdisk),v.status==='running'?Math.round((v.cpu||0)*100):'',v.uptime?Math.round(v.uptime/3600):'',guestTagList(v).join(' '),isTemplate(v)?'ja':'']))],
 hosts:['Hosts','Hosts mit CPU-, RAM- und Gastbelegung.',()=>downloadCSV(`orbit-hosts-${stamp()}.csv`,['Cluster','Host','Status','CPU-Kerne','CPU-Last %','RAM gesamt (GiB)','RAM belegt (GiB)','RAM %','Gäste','davon laufend','Uptime (Tage)'],state.resources.filter(r=>r.type==='node').map(n=>{const g=state.resources.filter(v=>['qemu','lxc'].includes(v.type)&&v.connection_id===n.connection_id&&v.node===n.node);return[connName(n.connection_id),n.node,n.status,n.maxcpu,Math.round((n.cpu||0)*100),gib(n.maxmem),gib(n.mem),percent(n.mem||0,n.maxmem||0),g.length,g.filter(v=>v.status==='running').length,n.uptime?Math.round(n.uptime/86400):'']}))],
 storage:['Storage','Belegung je Storage und Host, geteilte Storages einmal.',()=>{const seen=new Set();return downloadCSV(`orbit-storage-${stamp()}.csv`,['Cluster','Storage','Host','Geteilt','Typ','Inhalt','Gesamt (GiB)','Belegt (GiB)','Belegt %','Frei (GiB)'],state.resources.filter(r=>r.type==='storage').filter(s=>{const k=s.connection_id+(s.shared?'':'/'+s.node)+'/'+s.storage;if(seen.has(k))return false;seen.add(k);return true}).map(s=>[connName(s.connection_id),s.storage,s.shared?'(geteilt)':s.node,s.shared?'ja':'nein',s.plugintype||'',s.content||'',gib(s.maxdisk),gib(s.disk),percent(s.disk||0,s.maxdisk||0),gib((s.maxdisk||0)-(s.disk||0))]))}],
 operations:['Orbit-Aktionen','Aktionen der letzten Zeit mit Benutzer und Ergebnis.',()=>downloadCSV(`orbit-aktionen-${stamp()}.csv`,['Zeit','Aktion','Gast','VMID','Host','Benutzer','Status','Letzte Meldung'],[...state.operations,...state.jobs].sort((a,b)=>(b.created||0)-(a.created||0)).map(o=>[new Date((o.created||0)*1000).toLocaleString('de-DE'),operationLabels[o.action]||o.action||'Bereitstellung',o.name||'',o.vmid||'',o.node||'',o.requested_by||'',o.status,(o.events||[]).slice(-1)[0]?.message||'']))],
 audit:['Audit-Protokoll','Die letzten 500 Einträge (nur Administratoren).',async()=>{const rows=state.mode==='demo'?[{at:Date.now()/1000,user:'admin',action:'login',details:'Demo'}]:await api('audit');return downloadCSV(`orbit-audit-${stamp()}.csv`,['Zeit','Benutzer','Aktion','Details'],rows.map(r=>[new Date(r.at*1000).toLocaleString('de-DE'),r.user||'',r.action,r.details]))},true]
};
function capacityReportHTML(){const now=new Date().toLocaleString('de-DE'),clusters=state.connections.filter(c=>c.kind!=='pbs');const sec=clusters.map(c=>{const nodes=state.resources.filter(r=>r.type==='node'&&r.connection_id===c.id),guests=state.resources.filter(r=>['qemu','lxc'].includes(r.type)&&r.connection_id===c.id&&!isTemplate(r)),seen=new Set(),stores=state.resources.filter(r=>r.type==='storage'&&r.connection_id===c.id).filter(s=>{const k=(s.shared?'':s.node+'/')+s.storage;if(seen.has(k))return false;seen.add(k);return true}),cpu=nodes.reduce((a,n)=>a+(n.maxcpu||0),0),vcpu=guests.reduce((a,v)=>a+(v.maxcpu||0),0),mem=nodes.reduce((a,n)=>a+(n.maxmem||0),0),used=nodes.reduce((a,n)=>a+(n.mem||0),0),alloc=guests.reduce((a,v)=>a+(v.maxmem||0),0);
return `<h2>${esc(c.name)}</h2><table class="kv"><tr><th>Hosts</th><td>${nodes.filter(n=>n.status==='online').length} von ${nodes.length} online</td><th>Gäste</th><td>${guests.length} (${guests.filter(v=>v.status==='running').length} laufend)</td></tr><tr><th>CPU</th><td>${cpu} Kerne · ${vcpu} vCPU zugewiesen (${cpu?(vcpu/cpu).toFixed(1).replace('.',','):'—'} : 1)</td><th>RAM</th><td>${fmtBytes(used)} von ${fmtBytes(mem)} belegt (${percent(used,mem)} %) · ${fmtBytes(alloc)} zugewiesen</td></tr></table>
<h3>Hosts</h3><table><thead><tr><th>Host</th><th>Status</th><th class="n">CPU-Last</th><th class="n">RAM</th><th class="n">Gäste</th></tr></thead><tbody>${nodes.map(n=>`<tr><td>${esc(n.node)}</td><td>${esc(n.status)}</td><td class="n">${Math.round((n.cpu||0)*100)} %</td><td class="n">${percent(n.mem||0,n.maxmem||0)} % · ${fmtBytes(n.mem||0)} / ${fmtBytes(n.maxmem||0)}</td><td class="n">${guests.filter(v=>v.node===n.node).length}</td></tr>`).join('')}</tbody></table>
<h3>Storage</h3><table><thead><tr><th>Storage</th><th>Host</th><th class="n">Belegt</th><th class="n">Frei</th></tr></thead><tbody>${stores.map(s=>{const p=percent(s.disk||0,s.maxdisk||0);return `<tr class="${p>=85?'crit':''}"><td>${esc(s.storage)}</td><td>${s.shared?'geteilt':esc(s.node)}</td><td class="n">${p} % · ${fmtBytes(s.disk||0)} / ${fmtBytes(s.maxdisk||0)}</td><td class="n">${fmtBytes((s.maxdisk||0)-(s.disk||0))}</td></tr>`}).join('')}</tbody></table>
<h3>Größte Gäste nach RAM</h3><table><thead><tr><th>Gast</th><th>Host</th><th>Status</th><th class="n">vCPU</th><th class="n">RAM</th></tr></thead><tbody>${guests.slice().sort((a,b)=>(b.maxmem||0)-(a.maxmem||0)).slice(0,10).map(v=>`<tr><td>${esc(v.name)} (${esc(v.vmid)})</td><td>${esc(v.node)}</td><td>${esc(v.status)}</td><td class="n">${esc(v.maxcpu)}</td><td class="n">${fmtBytes(v.maxmem||0)}</td></tr>`).join('')}</tbody></table>`}).join('');
return `<!doctype html><html lang="de"><head><meta charset="utf-8"><title>Orbit Kapazitätsbericht ${esc(stamp())}</title><style>body{font:12px/1.45 Inter,system-ui,sans-serif;color:#111827;margin:28px}h1{font-size:20px;margin:0 0 2px}h2{font-size:15px;margin:26px 0 8px;padding-top:12px;border-top:2px solid #ea580c}h3{font-size:12.5px;margin:14px 0 6px;color:#374151}p.meta{color:#6b7280;margin:0 0 10px}table{width:100%;border-collapse:collapse;margin-bottom:6px}th,td{text-align:left;padding:5px 8px;border-bottom:1px solid #e5e7eb;vertical-align:top}thead th{background:#f3f4f6;font-weight:600}table.kv th{width:12%;color:#6b7280;font-weight:500}.n{text-align:right;font-variant-numeric:tabular-nums}tr.crit td{color:#b91c1c;font-weight:600}@page{margin:14mm}</style></head><body><h1>Kapazitätsbericht</h1><p class="meta">Orbit Central · erstellt ${esc(now)} · ${clusters.length} Cluster</p>${sec||'<p>Keine Cluster verbunden.</p>'}</body></html>`}
function printCapacityReport(){const html=capacityReportHTML(),frame=document.createElement('iframe');frame.className='print-frame';frame.setAttribute('aria-hidden','true');document.body.append(frame);const d=frame.contentDocument;d.open();d.write(html);d.close();setTimeout(()=>{try{frame.contentWindow.focus();frame.contentWindow.print()}catch{}setTimeout(()=>frame.remove(),2000)},250);return html}
function reportsPage(){const admin=isAdmin(),guests=state.resources.filter(r=>['qemu','lxc'].includes(r.type)).length,nodes=state.resources.filter(r=>r.type==='node').length;
return head('','Berichte','Inventar und Auslastung als CSV (Excel-kompatibel, Semikolon) oder als druckbarer Kapazitätsbericht (PDF über den Druckdialog).',refreshButton())+`<section class="panel report-hero"><div><h2>Kapazitätsbericht</h2><p class="muted">Hosts, Storage, Überbuchung und größte Gäste aller ${state.connections.filter(c=>c.kind!=='pbs').length} Cluster auf einer Seite. Im Druckdialog „Als PDF speichern“ wählen.</p></div><button class="primary" data-report-print>${icon('file')} Bericht drucken / PDF</button></section><div class="report-grid">${Object.entries(reportDefs).filter(([,d])=>!d[3]||admin).map(([k,[title,desc]])=>`<section class="panel report-card"><span class="report-icon">${icon('file')}</span><div><h3>${esc(title)}</h3><p class="muted">${esc(desc)}</p></div><button type="button" data-report="${k}">CSV herunterladen</button></section>`).join('')}</div><p class="muted">Stand der Daten: aktueller Live-Zustand (${guests} Gäste, ${nodes} Hosts).</p>`}

/* Wiring -------------------------------------------------------------------- */
function bindAutomation(){
 $$('[data-edit-tags]').forEach(b=>b.onclick=()=>tagModal(b.dataset.editTags));
 const tf=$('#vm-tag-filter');if(tf)tf.onchange=()=>{state.vmTag=tf.value;render()};
 $$('[data-history-source]').forEach(b=>b.onclick=()=>{state.historySource=b.dataset.historySource;render()});
 $$('[data-history-refresh]').forEach(b=>b.onclick=()=>{const v=state.object?.vm;if(v)loadHistory(v,true)});
 $$('.history-panel [data-task-log]').forEach(b=>b.onclick=()=>openTaskLog(b.dataset.taskLog));
 $$('[data-schedule-edit]').forEach(b=>b.onclick=()=>scheduleModal(b.dataset.scheduleEdit));
 $$('[data-schedule-result]').forEach(b=>b.onclick=()=>{const sc=scheduleState().list.find(x=>x.id===b.dataset.scheduleResult);if(sc)scheduleResultModal(sc,sc.last_run)});
 $$('[data-schedule-run]').forEach(b=>b.onclick=()=>{const sc=scheduleState().list.find(x=>x.id===b.dataset.scheduleRun);if(!sc)return;openModal('GEPLANTE AKTION','Jetzt ausführen',`<p>„${esc(sc.name)}“ wird sofort ausgeführt: <b>${esc(scheduleActionNames[sc.action])}</b> für ${scheduleTarget(sc)}. Der reguläre Termin bleibt bestehen.</p><div class="modal-foot"><button data-cancel>Abbrechen</button><button class="primary" data-confirm-run>Ausführen</button></div>`);modal.querySelector('[data-confirm-run]').onclick=async()=>{setModalBusy(true);try{let run;if(state.mode==='demo'){run={at:Date.now()/1000,results:state.resources.filter(r=>['qemu','lxc'].includes(r.type)&&(sc.target==='tag'?guestTagList(r).includes(sc.tag):(sc.vmids||[]).includes(+r.vmid))).map(r=>({vmid:r.vmid,name:r.name,node:r.node,status:'queued'}))};sc.last_run=run}else{run=await api('schedules/'+encodeURIComponent(sc.id)+'/run',{method:'POST',body:'{}'});await loadSchedules(true)}setModalBusy(false);scheduleResultModal(sc,run);if(typeof refreshLive==='function')refreshLive()}catch(e){setModalBusy(false);toast(e.message)}}});
 $$('[data-schedule-delete]').forEach(b=>b.onclick=()=>{const sc=scheduleState().list.find(x=>x.id===b.dataset.scheduleDelete);if(!sc)return;openModal('GEPLANTE AKTION','Zeitplan löschen',`<p>„${esc(sc.name)}“ wird gelöscht. Bereits angelegte Snapshots und Backups bleiben erhalten.</p><div class="modal-foot"><button data-cancel>Abbrechen</button><button class="primary" data-confirm-delete>Löschen</button></div>`);modal.querySelector('[data-confirm-delete]').onclick=async()=>{setModalBusy(true);try{if(state.mode==='demo')scheduleState().demo.schedules=scheduleState().demo.schedules.filter(x=>x.id!==sc.id);else await api('schedules/'+encodeURIComponent(sc.id),{method:'DELETE'});closeModal(true);toast('Zeitplan gelöscht.');await loadSchedules(true);render()}catch(e){setModalBusy(false);toast(e.message)}}});
 $$('[data-report]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await reportDefs[b.dataset.report][2]();toast('Bericht erstellt.')}catch(e){toast(e.message)}finally{b.disabled=false}});
 $$('[data-report-print]').forEach(b=>b.onclick=()=>printCapacityReport());
 bindMaintenance();
}

/* Host maintenance, rolling reboots, host shell ---------------------------- */
Object.assign(icons,{wrench:'<path d="M14.7 6.3a4 4 0 0 0-5.4 5.4L3 18l3 3 6.3-6.3a4 4 0 0 0 5.4-5.4l-2.5 2.5-2.4-.6-.6-2.4z"/>',terminal:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="m7 9 3 3-3 3M13 15h4"/>'});
Object.assign(pageTitles,{maintenance:'Wartung & Updates'});Object.assign(pageIcons,{maintenance:'wrench'});
{const hw=infraNav.find(g=>g[0]==='Hardware');if(hw&&!hw[2].some(i=>i[0]==='maintenance'))hw[2].push(['maintenance','Wartung & Updates'])}
function maintState(){return state.maint||(state.maint={items:[],at:0,busy:false,error:'',updates:{}})}
function nodeMaintenance(cid,node){return maintState().items.find(d=>d.kind==='node'&&d.connection_id===cid&&d.node===node)}
function nodeInMaintenance(cid,node){return !!nodeMaintenance(cid,node)}
function rollingFor(cid){return maintState().items.find(d=>d.kind==='rolling'&&d.connection_id===cid)}
async function loadMaintenance(force=false){const m=maintState();if(m.busy||(!force&&m.at&&Date.now()-m.at<4000))return;m.busy=true;try{if(state.mode!=='demo')m.items=(await api('maintenance')).items||[];m.error=''}catch(e){m.error=e.message}finally{m.busy=false;m.at=Date.now()}if(['maintenance','clusters'].includes(state.page))(typeof renderLive==='function'?renderLive:render)()}
async function loadUpdates(cid,node,force=false){const m=maintState(),k=cid+'|'+node,e=m.updates[k]||(m.updates[k]={});if(e.busy||(!force&&e.at))return;e.busy=true;try{e.rows=state.mode==='demo'?(node==='pve-02'?[]:[{package:'pve-manager',old:'9.0.9',new:'9.0.10',priority:'important'},{package:'proxmox-kernel-6.14',old:'6.14.8-2',new:'6.14.11-1',priority:'optional'},{package:'openssl',old:'3.5.1-1',new:'3.5.1-1+deb13u1',priority:'important'}]):await api('connections/'+encodeURIComponent(cid)+'/updates?node='+encodeURIComponent(node));e.error=''}catch(x){e.error=x.message}finally{e.busy=false;e.at=Date.now()}if(state.page==='maintenance')render()}
const moveStatus={pending:['neutral','Wartet'],running:['warn','Läuft'],done:['ok','Verschoben'],failed:['fail','Fehler'],skipped:['neutral','Übersprungen']};
const moveTag=s=>{const[c,l]=moveStatus[s]||['neutral',s];return `<span class="status-tag ${c}"><span class="dot ${c==='warn'?'amber':''}"></span>${l}</span>`};
function maintBadge(d){if(!d)return '';const moves=d.moves||[],done=moves.filter(m=>['done','failed','skipped'].includes(m.status)).length;return d.state==='evacuating'?`<span class="status-tag warn maint-tag"><span class="dot amber"></span>Evakuierung ${done}/${moves.length}</span>`:d.state==='returning'?`<span class="status-tag warn maint-tag"><span class="dot amber"></span>Rückführung ${done}/${moves.length}</span>`:`<span class="status-tag maint maint-tag">${icon('wrench')} Wartung</span>`}
const rollingSteps={evacuate:'Gäste verschieben',reboot:'Neustart',wait:'Warten auf Host',return:'Gäste zurück'};
function rollingPanel(c,r){const nodes=r.nodes||[],idx=+r.index||0,stateTxt={running:'Läuft',paused:'Angehalten',done:'Abgeschlossen',cancelled:'Abgebrochen'}[r.state]||r.state;return `<div class="rolling ${esc(r.state)}"><div class="rolling-head"><div><b>Rolling-Neustart</b> <span class="muted">· gestartet ${esc(new Date(r.since*1000).toLocaleString('de-DE',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}))} von ${esc(r.by||'')}</span></div><span class="status-tag ${r.state==='running'?'warn':r.state==='done'?'ok':r.state==='paused'?'fail':'neutral'}"><span class="dot ${r.state==='running'?'amber':''}"></span>${esc(stateTxt)}</span></div><ol class="rolling-steps">${nodes.map((n,i)=>`<li class="${i<idx||r.state==='done'?'done':i===idx&&['running','paused'].includes(r.state)?'current':''}"><b>${esc(n)}</b><small>${i<idx||r.state==='done'?'fertig':i===idx&&['running','paused'].includes(r.state)?esc(rollingSteps[r.step]||r.step):'ausstehend'}</small></li>`).join('')}</ol>${r.error?`<div class="hint error">${esc(r.error)}</div>`:''}<details class="rolling-log"><summary>Protokoll (${(r.events||[]).length})</summary><ul>${(r.events||[]).slice(-12).reverse().map(e=>`<li><span class="mono muted">${esc(new Date(e.at*1000).toLocaleTimeString('de-DE'))}</span> ${esc(e.message)}</li>`).join('')}</ul></details><div class="rolling-actions">${r.state==='paused'?`<button type="button" class="primary" data-rolling="resume|${esc(c.id)}">Fortsetzen</button>`:''}${['running','paused'].includes(r.state)?`<button type="button" data-rolling="cancel|${esc(c.id)}">Abbrechen</button>`:`<button type="button" data-rolling="dismiss|${esc(c.id)}">Ausblenden</button>`}</div></div>`}
function maintenancePage(){const m=maintState(),admin=isAdmin(),clusters=state.connections.filter(c=>c.kind!=='pbs');if(!m.at&&!m.busy)setTimeout(loadMaintenance,0);
return head('','Wartung & Updates','Hosts in den Wartungsmodus versetzen (laufende Gäste werden automatisch live verschoben), Updates prüfen und installieren, Cluster Host für Host neu starten.',refreshButton())+(m.error?`<div class="hint error">${esc(m.error)}</div>`:'')+(clusters.length?clusters.map(c=>{const nodes=state.resources.filter(r=>r.type==='node'&&r.connection_id===c.id).sort((a,b)=>String(a.node).localeCompare(String(b.node),'de',{numeric:true})),roll=rollingFor(c.id);return `<section class="panel maint-cluster"><div class="table-toolbar"><h2>${esc(c.name)}</h2>${admin&&(!roll||!['running','paused'].includes(roll.state))?`<button type="button" data-rolling-start="${esc(c.id)}">${icon('refresh')} Rolling-Neustart</button>`:''}</div>${roll?rollingPanel(c,roll):''}<div class="table-wrap"><table class="data-table"><thead><tr><th>Host</th><th>Status</th><th class="num">Gäste laufend</th><th>Auslastung</th><th>Updates</th><th>Wartung</th><th></th></tr></thead><tbody>${nodes.map(n=>{const md=nodeMaintenance(c.id,n.node),run=state.resources.filter(v=>['qemu','lxc'].includes(v.type)&&v.connection_id===c.id&&v.node===n.node&&v.status==='running').length,u=m.updates[c.id+'|'+n.node];if(!u&&n.status==='online')setTimeout(()=>loadUpdates(c.id,n.node),0);const ref=esc(c.id)+'|'+esc(n.node);return `<tr><td><b>${esc(n.node)}</b></td><td>${statusTag(n.status)}</td><td class="num">${run}</td><td>${n.status==='online'?usageBar(percent(n.mem||0,n.maxmem||0),'RAM'):'—'}</td><td>${!u||u.busy&&!u.rows?'<span class="muted">…</span>':u.error?`<span class="text-fail" title="${esc(u.error)}">Nicht abrufbar</span>`:u.rows.length?`<button type="button" class="text-button" data-updates-show="${ref}">${u.rows.length} verfügbar</button>`:'<span class="muted">Aktuell</span>'}</td><td>${md?`<button type="button" class="text-button maint-open" data-maint-show="${ref}">${maintBadge(md)}</button>`:'<span class="muted">—</span>'}</td><td class="row-actions">${admin?`<details class="action-menu"><summary aria-label="Aktionen für ${esc(n.node)}">Aktionen ${icon('arrow')}</summary><div class="action-menu-list" role="menu">${md?`<button type="button" role="menuitem" data-maint-exit="${ref}" ${md.state==='active'?'':'disabled'}>Wartung beenden</button>`:`<button type="button" role="menuitem" data-maint-enter="${ref}" ${n.status==='online'?'':'disabled'}>Wartungsmodus starten</button>`}<button type="button" role="menuitem" data-host-shell="${ref}|" ${n.status==='online'?'':'disabled'}>Shell öffnen</button><button type="button" role="menuitem" data-host-shell="${ref}|upgrade" ${n.status==='online'?'':'disabled'}>Updates installieren</button><button type="button" role="menuitem" data-apt-refresh="${ref}" ${n.status==='online'?'':'disabled'}>Paketliste aktualisieren</button></div></details>`:''}</td></tr>`}).join('')}</tbody></table></div></section>`}).join(''):empty('server','Keine Cluster','Zuerst eine Proxmox-Verbindung einrichten.'))+`<p class="muted maint-note">Updates installiert Proxmox über <code>apt dist-upgrade</code> in einer Host-Shell – wie in der Proxmox-Oberfläche. Ablauf für Updates ohne Ausfall: Wartungsmodus → Updates installieren → Host neu starten (Rolling-Neustart) → Wartung beenden.</p>`}
function planTable(moves){return moves.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Gast</th><th>Ziel</th><th>Hinweis</th></tr></thead><tbody>${moves.map(m=>`<tr><td><b>${esc(m.name)}</b> <span class="muted mono">${esc(m.vmid)}</span> <span class="type-tag">${m.type==='lxc'?'LXC':'QEMU'}</span></td><td>${m.to?esc(m.to):'<span class="muted">—</span>'}</td><td>${m.status==='skipped'?`<span class="text-fail">${esc(m.message)}</span>`:m.local_disks?'<span class="muted">Mit lokalen Disks (dauert länger)</span>':m.status!=='pending'?moveTag(m.status)+(m.message?` <span class="muted">${esc(m.message)}</span>`:''):'<span class="muted">Live-Migration</span>'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Auf diesem Host laufen keine Gäste.</p>'}
function demoPlan(cid,node,restart){const others=state.resources.filter(r=>r.type==='node'&&r.connection_id===cid&&r.node!==node&&r.status==='online').map(r=>r.node);return state.resources.filter(v=>['qemu','lxc'].includes(v.type)&&v.connection_id===cid&&v.node===node&&v.status==='running').map((v,i)=>({vmid:v.vmid,name:v.name,type:v.type,from:node,...(v.type==='lxc'&&!restart?{status:'skipped',message:'Container läuft – Neustart-Migration nicht gewählt.'}:{status:'pending',to:others[i%others.length]})}))}
async function maintEnterModal(ref){const[cid,node]=ref.split('|');openModal('WARTUNGSMODUS',node,'<div class="loading">Evakuierungsplan wird berechnet …</div>');const epoch=modalEpoch;const plan=async restart=>state.mode==='demo'?demoPlan(cid,node,restart):(await api('maintenance/plan',{method:'POST',body:JSON.stringify({connection_id:cid,node,lxc_restart:restart})})).moves;
const draw=async restart=>{let moves;try{moves=await plan(restart)}catch(e){if(modalEpoch===epoch)modal.querySelector('.modal-body').innerHTML=`<div class="hint error">${esc(e.message)}</div><div class="modal-foot"><button data-cancel>Schließen</button></div>`;modal.querySelector('[data-cancel]').onclick=closeModal;return}if(modalEpoch!==epoch)return;
modal.querySelector('.modal-body').innerHTML=`<form id="maint-form"><p>Alle laufenden Gäste werden nacheinander per Live-Migration auf andere Hosts verschoben. Danach ist <b>${esc(node)}</b> frei für Updates, Hardwaretausch oder Neustart. Gestoppte Gäste bleiben auf dem Host.</p>${planTable(moves)}<label class="checkbox"><input type="checkbox" name="lxc_restart" ${restart?'checked':''}> Laufende Container per Neustart-Migration verschieben (kurze Unterbrechung)</label>${field('Notiz (optional)','note','',{optional:true,placeholder:'z. B. RAM-Tausch, Ticket 4711'})}<div data-form-error class="hint error"></div><div class="modal-foot"><button type="button" data-cancel>Abbrechen</button><button class="primary">Wartungsmodus starten</button></div></form>`;
modal.querySelector('[data-cancel]').onclick=closeModal;const form=$('#maint-form');form.elements.lxc_restart.onchange=()=>draw(form.elements.lxc_restart.checked);
form.onsubmit=async e=>{e.preventDefault();setModalBusy(true);try{if(state.mode==='demo'){maintState().items.push({id:'node:'+cid+'/'+node,kind:'node',connection_id:cid,node,state:'active',since:Date.now()/1000,by:'admin',note:form.elements.note.value,moves:moves.map(m=>m.status==='pending'?{...m,status:'done'}:m),events:[{at:Date.now()/1000,message:'Demo: Evakuierung simuliert.'}]});for(const m of moves)if(m.status==='pending'){const v=state.resources.find(r=>r.connection_id===cid&&r.vmid===m.vmid);if(v)v.node=m.to}}else await api('maintenance/enter',{method:'POST',body:JSON.stringify({connection_id:cid,node,note:form.elements.note.value,lxc_restart:form.elements.lxc_restart.checked})});closeModal(true);toast('Wartungsmodus gestartet.');await loadMaintenance(true);render()}catch(err){setModalBusy(false);formError(err.message)}}};
draw(false)}
function maintShowModal(ref){const[cid,node]=ref.split('|'),d=nodeMaintenance(cid,node);if(!d)return;openModal('WARTUNGSMODUS',node,`<dl class="facts"><dt>Status</dt><dd>${maintBadge(d)}</dd><dt>Seit</dt><dd>${esc(new Date(d.since*1000).toLocaleString('de-DE'))} · ${esc(d.by||'')}</dd>${d.note?`<dt>Notiz</dt><dd>${esc(d.note)}</dd>`:''}</dl>${planTable(d.moves||[])}<details class="rolling-log" open><summary>Protokoll</summary><ul>${(d.events||[]).slice(-10).reverse().map(e=>`<li><span class="mono muted">${esc(new Date(e.at*1000).toLocaleTimeString('de-DE'))}</span> ${esc(e.message)}</li>`).join('')}</ul></details><div class="modal-foot"><button data-cancel>Schließen</button></div>`)}
function maintExitModal(ref){const[cid,node]=ref.split('|'),d=nodeMaintenance(cid,node),moved=(d?.moves||[]).filter(m=>m.status==='done').length;openModal('WARTUNGSMODUS','Wartung beenden',`<form id="maint-exit"><p><b>${esc(node)}</b> wird wieder für Gäste freigegeben.</p>${moved?`<label class="checkbox"><input type="checkbox" name="return_guests" checked> ${moved} verschobene Gäste zurück auf ${esc(node)} migrieren</label>`:''}<div data-form-error class="hint error"></div><div class="modal-foot"><button type="button" data-cancel>Abbrechen</button><button class="primary">Wartung beenden</button></div></form>`);const form=$('#maint-exit');form.onsubmit=async e=>{e.preventDefault();setModalBusy(true);const back=!!form.elements.return_guests?.checked;try{if(state.mode==='demo'){if(back)for(const m of d.moves.filter(m=>m.status==='done')){const v=state.resources.find(r=>r.connection_id===cid&&r.vmid===m.vmid);if(v)v.node=node}maintState().items=maintState().items.filter(x=>x!==d)}else await api('maintenance/exit',{method:'POST',body:JSON.stringify({connection_id:cid,node,return_guests:back})});closeModal(true);toast(back?'Gäste werden zurückverschoben.':'Wartung beendet.');await loadMaintenance(true);render()}catch(err){setModalBusy(false);formError(err.message)}}}
function rollingModal(cid){const nodes=state.resources.filter(r=>r.type==='node'&&r.connection_id===cid).sort((a,b)=>String(a.node).localeCompare(String(b.node),'de',{numeric:true}));openModal('ROLLING-NEUSTART',state.connections.find(c=>c.id===cid)?.name||cid,`<form id="rolling-form"><p>Orbit startet die gewählten Hosts <b>nacheinander</b> neu: Gäste verschieben → Neustart → warten bis Host und Quorum zurück sind → Gäste zurück. Bei einem Problem hält der Ablauf an.</p><div class="rolling-pick">${nodes.map(n=>`<label class="checkbox"><input type="checkbox" name="node" value="${esc(n.node)}" ${n.status==='online'?'checked':'disabled'}> <b>${esc(n.node)}</b> <span class="muted">${n.status==='online'?state.resources.filter(v=>['qemu','lxc'].includes(v.type)&&v.connection_id===cid&&v.node===n.node&&v.status==='running').length+' Gäste laufend':'offline'}</span></label>`).join('')}</div><label class="checkbox"><input type="checkbox" name="return_guests" checked> Gäste nach dem Neustart zurückverschieben</label><label class="checkbox"><input type="checkbox" name="lxc_restart"> Laufende Container per Neustart-Migration verschieben</label><label class="checkbox"><input type="checkbox" name="acknowledge" required> Mir ist bewusst, dass die Hosts neu gestartet werden.</label><div data-form-error class="hint error"></div><div class="modal-foot"><button type="button" data-cancel>Abbrechen</button><button class="primary">Starten</button></div></form>`);
const form=$('#rolling-form');form.onsubmit=async e=>{e.preventDefault();const list=[...form.querySelectorAll('[name=node]:checked')].map(x=>x.value);if(!list.length){formError('Mindestens einen Host wählen.');return}setModalBusy(true);try{const body={connection_id:cid,nodes:list,return_guests:form.elements.return_guests.checked,lxc_restart:form.elements.lxc_restart.checked,acknowledge:form.elements.acknowledge.checked};if(state.mode==='demo')maintState().items.push({id:'rolling:'+cid,kind:'rolling',connection_id:cid,nodes:list,index:0,step:'evacuate',state:'running',since:Date.now()/1000,by:'admin',events:[{at:Date.now()/1000,message:'Demo: Rolling-Neustart simuliert.'}]});else await api('maintenance/rolling',{method:'POST',body:JSON.stringify(body)});closeModal(true);toast('Rolling-Neustart gestartet.');await loadMaintenance(true);render()}catch(err){setModalBusy(false);formError(err.message)}}}
function updatesModal(ref){const[cid,node]=ref.split('|'),u=maintState().updates[ref]||{};openModal('UPDATES',node,`${(u.rows||[]).length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Paket</th><th>Installiert</th><th>Neu</th><th>Priorität</th></tr></thead><tbody>${u.rows.map(p=>`<tr><td class="mono">${esc(p.package)}</td><td class="mono muted">${esc(p.old||'—')}</td><td class="mono">${esc(p.new)}</td><td>${esc(p.priority||'')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Keine Updates verfügbar.</p>'}<p class="muted">Kernel-Updates werden erst nach einem Neustart aktiv. Vorher den Host in den Wartungsmodus versetzen.</p><div class="modal-foot"><button data-cancel>Schließen</button>${isAdmin()?`<button class="primary" data-host-shell="${esc(cid)}|${esc(node)}|upgrade">Updates installieren</button>`:''}</div>`);const b=modal.querySelector('[data-host-shell]');if(b)b.onclick=()=>hostShell(cid,node,'upgrade')}
/* Keyboard text injection for noVNC: types text as key presses (paste into guests without clipboard support). */
async function typeIntoConsole(rfb,text){const special={'\n':0xff0d,'\r':null,'\t':0xff09};let n=0;for(const ch of String(text)){if(ch in special){if(special[ch])rfb.sendKey(special[ch],ch==='\n'?'Enter':'Tab');}else{const cp=ch.codePointAt(0);rfb.sendKey(cp<0x100?cp:0x01000000+cp,null)}if(++n%40===0)await new Promise(r=>setTimeout(r,25))}}
function pasteModal(getRFB){const prev=modal.open?null:true;openModal('KONSOLE','Text einfügen',`<form id="paste-form"><label for="f-paste">Text, der als Tastatureingabe gesendet wird</label><textarea id="f-paste" name="paste" rows="6" spellcheck="false" placeholder="z. B. ein langes Passwort oder einen Befehl"></textarea><p class="muted">Geht an das Tastaturlayout des Gastes (US-Layout empfohlen). Zeilenumbrüche werden als Enter gesendet.</p><div class="modal-foot"><button type="button" data-cancel>Abbrechen</button><button class="primary">Senden</button></div></form>`);$('#paste-form').onsubmit=async e=>{e.preventDefault();const rfb=getRFB(),text=$('#f-paste').value;if(!rfb){toast('Konsole ist nicht verbunden.');return}closeModal(true);await typeIntoConsole(rfb,text);toast(`${[...text].length} Zeichen gesendet.`)};void prev}
let shellRFB=null;
async function hostShell(cid,node,cmd=''){if(shellRFB){shellRFB.disconnect();shellRFB=null}openModal('HOST-SHELL',node+(cmd==='upgrade'?' · Updates installieren':''),`<div class="shell-wrap"><div class="console-controls"><span id="shell-state" class="console-status status-connecting">${state.mode==='demo'?'Demo':'Verbinde …'}</span><div class="console-control-actions"><button type="button" data-shell-paste>Text einfügen</button><button type="button" data-shell-full>Vollbild</button></div></div><div id="shell-screen" class="console-screen shell-screen"><div class="console-placeholder">${state.mode==='demo'?'<b>Host-Shell in der Live-Installation</b><span>Die Beispielumgebung verbindet sich mit keinem echten Host.</span>':'<b>Shell wird verbunden</b><span>Proxmox öffnet eine Shell auf dem Host.</span>'}</div></div><p class="muted">Läuft als Benutzer des API-Tokens. Für Nicht-root-Tokens fragt Proxmox ggf. nach einer Anmeldung. Jede geöffnete Shell wird protokolliert.</p></div><div class="modal-foot"><button data-cancel>Schließen</button></div>`);modal.classList.add('modal-wide');const epoch=modalEpoch,label=$('#shell-state'),screen=$('#shell-screen');
modal.querySelector('[data-shell-paste]').onclick=()=>{const t=prompt('Text als Tastatureingabe senden:');if(t&&shellRFB)typeIntoConsole(shellRFB,t)};modal.querySelector('[data-shell-full]').onclick=()=>screen.requestFullscreen?.();
const done=()=>{if(shellRFB){shellRFB.disconnect();shellRFB=null}modal.classList.remove('modal-wide')};modal.addEventListener('close',done,{once:true});if(state.mode==='demo')return;
try{const {default:RFB}=await import('/vendor/novnc/core/rfb.js');const info=await api('consoles',{method:'POST',body:JSON.stringify({connection_id:cid,node,shell:true,cmd,width:Math.max(16,Math.min(4096,Math.floor(screen.clientWidth||1000))),height:Math.max(16,Math.min(2160,Math.floor(screen.clientHeight||560)))})});if(modalEpoch!==epoch)return;screen.innerHTML='';const rfb=new RFB(screen,(location.protocol==='https:'?'wss://':'ws://')+location.host+'/api/consoles/'+info.id,{credentials:{password:info.password||info.ticket}});shellRFB=rfb;rfb.background='#080c14';rfb.scaleViewport=true;rfb.addEventListener('connect',()=>{label.textContent='Verbunden';label.className='console-status status-connected';rfb.focus()});rfb.addEventListener('disconnect',()=>{label.textContent='Getrennt';label.className='console-status status-disconnected';if(shellRFB===rfb)shellRFB=null})}catch(e){if(modalEpoch!==epoch)return;label.textContent='Fehler';label.className='console-status status-error';screen.innerHTML=`<div class="console-placeholder"><b>Shell nicht verfügbar</b><span>${esc(e.message)}</span></div>`}}
function bindMaintenance(){
 $$('[data-maint-enter]').forEach(b=>b.onclick=()=>maintEnterModal(b.dataset.maintEnter));
 $$('[data-maint-exit]').forEach(b=>b.onclick=()=>maintExitModal(b.dataset.maintExit));
 $$('[data-maint-show]').forEach(b=>b.onclick=()=>maintShowModal(b.dataset.maintShow));
 $$('[data-updates-show]').forEach(b=>b.onclick=()=>updatesModal(b.dataset.updatesShow));
 $$('#page [data-host-shell]').forEach(b=>b.onclick=()=>{const[cid,node,cmd]=b.dataset.hostShell.split('|');hostShell(cid,node,cmd||'')});
 $$('[data-rolling-start]').forEach(b=>b.onclick=()=>rollingModal(b.dataset.rollingStart));
 $$('[data-rolling]').forEach(b=>b.onclick=async()=>{const[act,cid]=b.dataset.rolling.split('|');if(act==='cancel'&&!confirm('Rolling-Neustart abbrechen? Ein Host im Wartungsmodus bleibt markiert.'))return;b.disabled=true;try{if(state.mode==='demo'){const r=rollingFor(cid);if(act==='dismiss')maintState().items=maintState().items.filter(x=>x!==r);else r.state=act==='cancel'?'cancelled':'running'}else await api('maintenance/rolling/'+act,{method:'POST',body:JSON.stringify({connection_id:cid})});await loadMaintenance(true);render()}catch(e){toast(e.message)}finally{b.disabled=false}});
 $$('[data-apt-refresh]').forEach(b=>b.onclick=async()=>{const[cid,node]=b.dataset.aptRefresh.split('|');try{if(state.mode!=='demo')await api('maintenance/apt-refresh',{method:'POST',body:JSON.stringify({connection_id:cid,node})});toast('Paketliste wird aktualisiert (Proxmox-Task).');setTimeout(()=>loadUpdates(cid,node,true),state.mode==='demo'?0:8000)}catch(e){toast(e.message)}});
 const paste=$('#console-paste');if(paste)paste.onclick=()=>pasteModal(()=>state.consoleRFB);
 if(state.authenticated&&['maintenance','clusters','drs'].includes(state.page))loadMaintenance();
}
setInterval(()=>{if(state.authenticated&&!document.hidden&&(state.page==='maintenance'||maintState().items.some(d=>['evacuating','returning','running'].includes(d.state))))loadMaintenance(true)},5000);
